/**
* 显示坐标 → 原图坐标
*
* <p>旋转 90°：显示系的 (x, y) 对应原图的 (h - y, x)；
* 180°：对应 (w - x, h - y)；
* 270°：对应 (y, w - x)。</p>
*
* @param relX   相对 stage 左边缘的距离（视口像素）
* @param relY   相对 stage 上边缘的距离（视口像素）
* @param scale  当前显示缩放倍数
* @param disp   图片的显示尺寸（**原图像素**量纲，未乘 scale；旋转 90/270 时已转置）
* @param nat    原图像素尺寸
* @param rot    当前旋转角
* @returns 换算到原图坐标系、并夹取到 {@code [0, nat.w] × [0, nat.h]} 的坐标
*/
function displayToImage(relX, relY, scale, disp, nat, rot) {
	const s = Number.isFinite(scale) && scale > 0 ? scale : 1;
	const ux = relX / s;
	const uy = relY / s;
	let x;
	let y;
	if (rot === 90) {
		x = uy;
		y = disp.w - ux;
	} else if (rot === 180) {
		x = disp.w - ux;
		y = disp.h - uy;
	} else if (rot === 270) {
		x = disp.h - uy;
		y = ux;
	} else {
		x = ux;
		y = uy;
	}
	return {
		x: clamp(x, 0, nat.w),
		y: clamp(y, 0, nat.h)
	};
}
/**
* 把坐标夹取到区间内
*
* @param v 值
* @param lo 下界
* @param hi 上界
* @returns 夹取后的值；上界小于下界时返回下界
*/
function clamp(v, lo, hi) {
	if (!Number.isFinite(v)) return lo;
	if (hi < lo) return lo;
	return Math.max(lo, Math.min(hi, v));
}
